def transform(grid):
    result = []
    for row in grid:
        if not row:
            result.append(row)
            continue
        anchor = row[0]

        if anchor == 3:
            # Background starts the row: 3s stay, 8s become 1s
            new_row = [cell if cell == 3 else 1 for cell in row]
        else:
            # Pattern starts the row: 8s stay, 3s become 1s
            new_row = [cell if cell == 8 else 1 for cell in row]
        result.append(new_row)

    return result
